response.body:
{
  "openapi": "1.0.0",
  "info": {
    "title": "OpenAPI example",
    "version": "1.0.0"
  },
  "webhooks": {
    "newPet": {
      "post": {
        "requestBody": {
          "decription": "Information about a new pet in the system",
          "content": {
            "application/json": {
              "schema": {
                "title": "Schema for an API specs version",
                "type": "object",
                "properties": {
                  "id": {
                    "type": "number"
                  },
                  "name": {
                    "type": "string"
                  }
                }
              }
            }
          },
          "responses": {
            "200": {
              "description": "Return a 200 status to indicate that the data was received successfully"
            }
          }
        }
      }
    }
  }
}
